 async function loadChallenges(){const el=$('#challengesAdmin');if(!el)return;const {data,error}=await db.from('team_challenges').select('id,challenging_team_id,challenged_team_id,leader_callsign,leader_mobile,proposed_format,proposed_date,message,status,created_at,challenging:teams!team_challenges_challenging_team_id_fkey(name),challenged:teams!team_challenges_challenged_team_id_fkey(name)').eq('status','pending').order('created_at');if(error){el.innerHTML=`<p class="admin-error">${esc(adminError(error))}</p>`;return}if(!data?.length){el.innerHTML='<div class="empty-state">No pending squad challenges.</div>';return}el.innerHTML=data.map(c=>`<article class="application-card"><div class="application-heading"><div><span class="application-label">SQUAD CHALLENGE</span><h3>${esc(c.challenging?.name||'Team')} vs ${esc(c.challenged?.name||'Team')}</h3></div><span class="pending-pill">PENDING</span></div><div class="application-details"><span><b>Requesting leader</b>${esc(c.leader_callsign)}</span><span><b>Contact</b>${esc(c.leader_mobile)}</span><span><b>Format</b>${esc(c.proposed_format)}</span><span><b>Proposed date</b>${esc(c.proposed_date||'Flexible')}</span><span><b>Message</b>${esc(c.message||'—')}</span></div><div class="application-actions"><button class="button button-lime" data-challenge-action="accept" data-id="${c.id}">ACCEPT</button><button class="button button-danger" data-challenge-action="reject" data-id="${c.id}">REJECT</button></div></article>`).join('');el.querySelectorAll('[data-challenge-action]').forEach(btn=>btn.addEventListener('click',async()=>{if(!confirm('Mark this challenge '+btn.dataset.challengeAction+'ed?'))return;const {error}=await db.rpc('review_team_challenge',{challenge_id:btn.dataset.id,decision:btn.dataset.challengeAction});if(error)msg($('#adminStatus'),error.message||adminError(error),'error');else{msg($('#adminStatus'),'Challenge '+btn.dataset.challengeAction+'ed. Please contact the challenged team leader manually; no automatic WhatsApp alert is sent.','success');await loadChallenges()}}))}

 async function loadFeedback(){const el=$('#feedbackAdmin');if(!el)return;let query=db.from('feedback').select('id,display_name,rating,comment,published,created_at,field_id,arena_fields(name)').order('created_at',{ascending:false}).limit(150);const filter=$('#feedbackAdminFieldFilter')?.value||'all';if(filter!=='all')query=query.eq('field_id',filter);const {data,error}=await query;if(error){el.innerHTML=`<p class="admin-error">${esc(adminError(error))}</p>`;return}if(!data?.length){el.innerHTML='<div class="empty-state">No player feedback for this field.</div>';return}el.innerHTML=data.map(f=>`<article class="admin-feedback-row"><div class="feedback-admin-head"><b>${esc(f.display_name||'FIELDZERO PLAYER')}</b><span>${'★'.repeat(Number(f.rating)||0)}${'☆'.repeat(5-(Number(f.rating)||0))} · ${Number(f.rating)}/5</span><small>${esc(f.arena_fields?.name||'Field not assigned')} · ${new Date(f.created_at).toLocaleString()}</small></div><p>${esc(f.comment)}</p><button class="button button-danger" data-delete-feedback="${f.id}" data-feedback-name="${esc(f.display_name||'player')}">DELETE FEEDBACK</button></article>`).join('');el.querySelectorAll('[data-delete-feedback]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm(`Delete feedback from ${b.dataset.feedbackName}?`))return;const {error}=await db.from('feedback').delete().eq('id',b.dataset.deleteFeedback);if(error){msg($('#adminStatus'),adminError(error),'error');return}msg($('#adminStatus'),'Feedback removed.','success');await loadFeedback()}))}

 async function loadFieldsAdmin(){
  const {data,error}=await db.from('arena_fields').select('id,name,address,google_maps_url,latitude,longitude,active,is_main,slug,commission_rate,network_status').order('name');
  if(error){const host=$('#fieldsAdmin');if(host)host.innerHTML=`<p class="admin-error">${esc(error.message||adminError(error))}</p>`;return;}
  const rows=data||[],active=rows.filter(f=>f.active&&f.network_status==='active');
  adminFieldCache=rows;mainAdminFieldId=(rows.find(f=>f.is_main)||{}).id||'';
  const financeFilter=$('#finFieldFilter');if(financeFilter){const old=financeFilter.value||'all';financeFilter.innerHTML='<option value="all">ALL FIELDZERO LOCATIONS</option>'+rows.map(f=>`<option value="${f.id}">${esc(f.name)}${f.is_main?' · MAIN':''}${f.active&&f.network_status==='active'?'':' · SUSPENDED'}</option>`).join('');financeFilter.value=[...financeFilter.options].some(o=>o.value===old)?old:'all';}
  const invoiceField=$('#finInvoiceFieldSelect');if(invoiceField){const old=invoiceField.value;invoiceField.innerHTML=active.map(f=>`<option value="${f.id}">${esc(f.name)}${f.is_main?' · MAIN':''}</option>`).join('');invoiceField.value=active.some(f=>f.id===old)?old:(mainAdminFieldId||active[0]?.id||'');}
  const accountField=$('#finAccountFieldSelect');if(accountField){const old=accountField.value;accountField.innerHTML=active.map(f=>`<option value="${f.id}">${esc(f.name)}${f.is_main?' · MAIN':''}</option>`).join('');accountField.value=active.some(f=>f.id===old)?old:(financeFilter?.value&&financeFilter.value!=='all'?financeFilter.value:(mainAdminFieldId||active[0]?.id||''));}
  if($('#finFieldFilter')&&$('#finFieldFilter').dataset.listenerReady!=='1'){ $('#finFieldFilter').dataset.listenerReady='1'; $('#finFieldFilter').addEventListener('change',()=>loadFinanceAll()); }
  [['#eventFieldSelect','Choose a field…'],['#galleryFieldSelect','Choose a field…'],['#spotlightFieldSelect','Choose a field…']].forEach(([selector])=>{const sel=$(selector);if(!sel)return;const previous=sel.value;sel.innerHTML=active.map(f=>`<option value="${f.id}">${esc(f.name)}${f.is_main?' · MAIN':''}</option>`).join('');if(active.some(f=>f.id===previous))sel.value=previous;else sel.value=(active.find(f=>f.is_main)||active[0])?.id||'';});
  ['#fzBookingFieldFilter','#feedbackAdminFieldFilter','#galleryAdminFieldFilter','#eventsAdminFieldFilter','#fzSpotlightAdminFieldFilter','#franchiseEventsFieldFilter','#fzAdsFieldFilter'].forEach(selector=>{const sel=$(selector);if(!sel)return;const previous=sel.value||'all';sel.innerHTML='<option value="all">ALL FIELDZERO FIELDS</option>'+rows.map(f=>`<option value="${f.id}">${esc(f.name)}${f.is_main?' · MAIN':''}</option>`).join('');sel.value=[...sel.options].some(o=>o.value===previous)?previous:'all';});
  ['#franchiseCommissionFieldFilter'].forEach(selector=>{const sel=$(selector);if(!sel)return;const previous=sel.value||'all';sel.innerHTML='<option value="all">ALL FRANCHISE FIELDS</option>'+active.filter(f=>!f.is_main).map(f=>`<option value="${f.id}">${esc(f.name)}</option>`).join('');sel.value=[...sel.options].some(o=>o.value===previous)?previous:'all';});
  ['#fzBookingFieldFilter','#feedbackAdminFieldFilter','#galleryAdminFieldFilter','#eventsAdminFieldFilter','#fzSpotlightAdminFieldFilter','#franchiseEventsFieldFilter','#franchiseCommissionFieldFilter','#fzAdsFieldFilter'].forEach(selector=>{const sel=$(selector);if(!sel||sel.dataset.listenerReady==='1')return;sel.dataset.listenerReady='1';sel.addEventListener('change',()=>{if(selector==='#fzBookingFieldFilter'){fzLoadBookingDays();fzLoadSpecialRequests()}else if(selector==='#feedbackAdminFieldFilter')loadFeedback();else if(selector==='#galleryAdminFieldFilter')loadGalleryAdmin();else if(selector==='#eventsAdminFieldFilter')loadEvents();else if(selector==='#fzSpotlightAdminFieldFilter')fzLoadSpotlights();else if(selector==='#franchiseEventsFieldFilter')window.dispatchEvent(new CustomEvent('fz-franchise-events-filter'));else if(selector==='#franchiseCommissionFieldFilter')window.dispatchEvent(new CustomEvent('fz-franchise-commission-filter'));else if(selector==='#fzAdsFieldFilter')window.dispatchEvent(new CustomEvent('fz-franchise-ads-filter'));});});
  const host=$('#fieldsAdmin');if(host){host.innerHTML=rows.map(f=>`<article class="field-record-card"><div class="field-record-main"><span class="field-record-kicker">${f.is_main?'MAIN FIELD · 0% COMMISSION':`FRANCHISE · ${Number(f.commission_rate||10)}% COMMISSION`}</span><h4>${esc(f.name)}</h4><p>${esc(f.address||'Address not set')} · ${f.active&&f.network_status==='active'?'ACTIVE':'SUSPENDED / HIDDEN'}</p><small>Field setup and suspension are controlled in the FIELDZERO NETWORK panel. Historical records are retained.</small></div></article>`).join('')||'<div class="empty-state">No field records are available.</div>';}
 }
 $('#fieldForm')?.addEventListener('submit',async e=>{e.preventDefault();msg($('#fieldAdminStatus'),'Use the public Field Partnership request so the owner account and commission settings are created together.','error');});
 async function loadEvents(){
  const el=$("#eventsAdmin");if(!el)return;
  let eventQuery=db.from("events").select("id,title,event_type,event_date,start_time,end_time,registration_deadline,published,price_amount,price_currency,field_id,location,popup_featured,arena_fields(name)").order("event_date",{ascending:false});const eventField=$('#eventsAdminFieldFilter')?.value||'all';if(eventField!=='all')eventQuery=eventQuery.eq('field_id',eventField);const {data,error}=await eventQuery;
  if(error){el.innerHTML=`<p class="admin-error">${esc(error.message||adminError(error))} Apply the V9 migration if the popup setting is missing.</p>`;return;}
  if(!data?.length){el.innerHTML='<div class="empty-state">No events published yet. Events you create will appear here.</div>';return;}
  el.innerHTML=data.map(ev=>`<article class="admin-event-row"><div><b>${esc(ev.title)}</b><small>${esc(ev.event_type||"Event")} · ${esc(ev.event_date||"Date TBA")} · ${esc(ev.start_time||"")}${ev.end_time?"–"+esc(ev.end_time):""} · Field: ${esc(ev.arena_fields?.name||ev.location||"Not assigned")} · ${ev.published?"Published":"Draft"}</small><div class="event-price-editor"><label>Event price <input type="number" min="0" max="99999999" step="0.01" value="${Number(ev.price_amount||0)}" data-event-price="${ev.id}"></label><label>Currency <select data-event-currency="${ev.id}"><option value="LKR" ${ev.price_currency==='LKR'?'selected':''}>LKR</option><option value="USD" ${ev.price_currency==='USD'?'selected':''}>USD</option></select></label><button class="button button-lime" data-save-event-price="${ev.id}">SAVE PRICE</button></div><small class="event-popup-status">Public pop-up: ${ev.popup_featured?"ENABLED":"DISABLED"}</small></div><div class="admin-event-controls"><button class="button button-ghost" data-toggle-event-popup="${ev.id}" data-featured="${ev.popup_featured}">${ev.popup_featured?"DISABLE EVENT POP-UP":"ENABLE EVENT POP-UP"}</button><button class="button button-danger" data-delete-event="${ev.id}" data-title="${esc(ev.title)}">DELETE EVENT</button></div></article>`).join("");
  el.querySelectorAll('[data-save-event-price]').forEach(btn=>btn.addEventListener('click',async()=>{const id=btn.dataset.saveEventPrice,price=Number(el.querySelector(`[data-event-price="${id}"]`).value),currency=el.querySelector(`[data-event-currency="${id}"]`).value;if(!Number.isFinite(price)||price<0){msg($('#adminStatus'),'Enter a valid non-negative price.','error');return;}const {error}=await db.from('events').update({price_amount:price,price_currency:currency}).eq('id',id);if(error){msg($('#adminStatus'),error.message||adminError(error),'error');return;}msg($('#adminStatus'),'Event price updated.','success');await loadEvents();}));
  el.querySelectorAll('[data-toggle-event-popup]').forEach(btn=>btn.addEventListener('click',async()=>{const next=btn.dataset.featured!=='true';const {error}=await db.from('events').update({popup_featured:next}).eq('id',btn.dataset.toggleEventPopup);if(error){msg($('#adminStatus'),error.message||adminError(error),'error');return;}msg($('#adminStatus'),`Event pop-up ${next?'enabled':'disabled'}.`,'success');await loadEvents();}));
  el.querySelectorAll("[data-delete-event]").forEach(btn=>btn.addEventListener("click",async()=>{const title=btn.dataset.title;if(!confirm(`Permanently delete event “${title}”? Its event registrations and scoreboard results may also be deleted. This cannot be undone.`))return;const {error}=await db.from("events").delete().eq("id",btn.dataset.deleteEvent);if(error){msg($("#adminStatus"),error.message||adminError(error),"error");return;}msg($("#adminStatus"),`Event “${title}” deleted.`,"success");await Promise.all([loadEvents(),loadResultOptions(),loadEventRegistrations()]);}));
 }


 async function loadSiteSettingsAdmin(){
  const form=$("#siteSettingsForm");if(!form)return;
  const {data,error}=await db.from("site_settings").select("id,opening_soon_enabled,opening_soon_title,opening_soon_message").eq("id",1).maybeSingle();
  if(error){msg($("#siteSettingsStatus"),"Could not load launch settings. Apply the V9 migration and try again.","error");return;}
  if(!data){msg($("#siteSettingsStatus"),"No saved launch settings found. Run the V9 migration.","error");return;}
  form.elements.namedItem("opening_soon_enabled").checked=!!data.opening_soon_enabled;
  form.elements.namedItem("opening_soon_title").value=data.opening_soon_title||"OPENING SOON";
  form.elements.namedItem("opening_soon_message").value=data.opening_soon_message||"";
 }
