  let ty=boxY+17;totalRows.forEach((r,i)=>{const strong=i>=totalRows.length-2;doc.setFont('helvetica',strong?'bold':'normal');doc.setFontSize(strong?8.5:6.5);doc.setTextColor(...(strong?lime:white));doc.text(r[0],20,ty);doc.text(`LKR ${r[1]}`,190,ty,{align:'right'});ty+=6.2;});
  y=boxY+boxH+7;
  if(pay){
    if(y>257){pageFooter();doc.addPage();drawHeader();y=69;}
    doc.setFillColor(...light);doc.roundedRect(14,y,182,27,2,2,'F');doc.setTextColor(...dark);doc.setFont('helvetica','bold');doc.setFontSize(7.2);doc.text(isAdvance?'ADVANCE PAYMENT VERIFIED':'PAYMENT RECEIVED',19,y+7);
    doc.setFont('helvetica','normal');doc.setFontSize(6.8);doc.setTextColor(...muted);
    doc.text(`${financeDate(pay.payment_date)} · ${String(pay.payment_method||'').toUpperCase()} · ${pay.receipt_number}`,19,y+14);
    if(pay.reference)doc.text(`Reference: ${String(pay.reference).slice(0,72)}`,19,y+21);
    doc.setFont('helvetica','bold');doc.setFontSize(11);doc.setTextColor(...dark);doc.text(`LKR ${fmt(pay.amount)}`,190,y+14,{align:'right'});y+=33;
  }
  if(booking.advance_verified_at){doc.setFont('helvetica','bold');doc.setFontSize(7);doc.setTextColor(...muted);doc.text(`ADVANCE VERIFIED · ${new Date(booking.advance_verified_at).toLocaleString('en-GB',{timeZone:'Asia/Colombo'})}`,14,y);y+=6;}
  if(inv.notes||inv.terms||settings.payment_instructions){if(y>260){pageFooter();doc.addPage();drawHeader();y=69;}doc.setFont('helvetica','bold');doc.setFontSize(6.7);doc.setTextColor(...dark);doc.text('NOTES / TERMS',14,y);y+=5;doc.setFont('helvetica','normal');doc.setFontSize(6.5);doc.setTextColor(...muted);[inv.notes,inv.terms,settings.payment_instructions].filter(Boolean).forEach(t=>{const lines=doc.splitTextToSize(String(t),180);if(y+lines.length*3.5>278){pageFooter();doc.addPage();drawHeader();y=69;}doc.text(lines,14,y);y+=lines.length*3.5+2;});}
  pageFooter();
  const blob=doc.output('blob');let archiveMessage='';
  if(pay){const path=`invoices/${inv.invoice_date.slice(0,4)}/${financeFileSafe(inv.invoice_number)}-${pay.id}.pdf`;try{const up=await db.storage.from('fz-finance-documents').upload(path,blob,{contentType:'application/pdf',upsert:true});if(up.error)archiveMessage=' Private archive upload failed: '+up.error.message;else{const upd=await db.from('fz_invoice_payments').update({pdf_path:path}).eq('id',pay.id);if(upd.error)archiveMessage=' Private archive path could not be saved: '+upd.error.message}}catch(archiveError){archiveMessage=' Private archive upload could not be completed: '+(archiveError.message||'network error')}}
